// NULL-tolerant scan buffer for sharedKeyScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type sharedKeyPreloadBuf struct {
	ID        sql.Null[uuid.UUID]
	OwnerID   sql.Null[string]
	Version   sql.Null[string]
	PublicKey sql.Null[string]
	Status    sql.Null[string]
	CreatedAt sql.Null[time.Time]
	RetiredAt sql.Null[time.Time]
}

// sharedKeyScanMapperNullable maps the preloaded sharedKey
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func sharedKeyScanMapperNullable(prefix string) scan.Mapper[*SharedKey] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*SharedKey, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *sharedKeyPreloadBuf) any
		}
		targets := make([]target, 0, 7)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *sharedKeyPreloadBuf) any { return &b.ID }})
			case "owner_id":
				targets = append(targets, target{i, func(b *sharedKeyPreloadBuf) any { return &b.OwnerID }})
			case "version":
				targets = append(targets, target{i, func(b *sharedKeyPreloadBuf) any { return &b.Version }})
			case "public_key":
				targets = append(targets, target{i, func(b *sharedKeyPreloadBuf) any { return &b.PublicKey }})
			case "status":
				targets = append(targets, target{i, func(b *sharedKeyPreloadBuf) any { return &b.Status }})
			case "created_at":
				targets = append(targets, target{i, func(b *sharedKeyPreloadBuf) any { return &b.CreatedAt }})
			case "retired_at":
				targets = append(targets, target{i, func(b *sharedKeyPreloadBuf) any { return &b.RetiredAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(sharedKeyPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*SharedKey, error) {
				buf := link.(*sharedKeyPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.Valid) &&
					!(buf.OwnerID.Valid) &&
					!(buf.Version.Valid) &&
					!(buf.PublicKey.Valid) &&
					!(buf.Status.Valid) &&
					!(buf.CreatedAt.Valid) &&
					!(buf.RetiredAt.Valid) {
					return nil, nil
				}

				o := new(SharedKey)
				if buf.ID.Valid {
					o.ID = buf.ID.V
				}
				if buf.OwnerID.Valid {
					o.OwnerID = buf.OwnerID.V
				}
				if buf.Version.Valid {
					o.Version = buf.Version.V
				}
				if buf.PublicKey.Valid {
					o.PublicKey = buf.PublicKey.V
				}
				if buf.Status.Valid {
					o.Status = buf.Status.V
				}
				if buf.CreatedAt.Valid {
					o.CreatedAt = buf.CreatedAt.V
				}
				o.RetiredAt = buf.RetiredAt
				return o, nil
			}
	}
}

func (o *SharedKey) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "DeviceKeys":
		rels, ok := retrieved.(DeviceKeySlice)
		if !ok {
			return fmt.Errorf("sharedKey cannot load %T as %q", retrieved, name)
		}

		o.R.DeviceKeys = rels
		o.R.Loaded.DeviceKeys = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.SharedKey = o
				rel.R.Loaded.SharedKey = true
			}
		}
		return nil
	case "Videos":
		rels, ok := retrieved.(VideoSlice)
		if !ok {
			return fmt.Errorf("sharedKey cannot load %T as %q", retrieved, name)
		}

		o.R.Videos = rels
		o.R.Loaded.Videos = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.SharedKey = o
				rel.R.Loaded.SharedKey = true
			}
		}
		return nil
	default:
		return fmt.Errorf("sharedKey has no relationship %q", name)
	}
}

