// LoadDeviceKeys loads the sharedKey's DeviceKeys into the .R struct
func (o *SharedKey) LoadDeviceKeys(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.DeviceKeys = nil
	o.R.Loaded.DeviceKeys = false

	related, err := o.DeviceKeys(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.SharedKey = o
		rel.R.Loaded.SharedKey = true
	}

	o.R.DeviceKeys = related
	o.R.Loaded.DeviceKeys = true
	return nil
}

// LoadDeviceKeys loads the sharedKey's DeviceKeys into the .R struct
func (os SharedKeySlice) LoadDeviceKeys(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	deviceKeys, err := os.DeviceKeys(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.DeviceKeys = nil
		o.R.Loaded.DeviceKeys = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	sharedKeyByKey := make(map[uuid.UUID][]*SharedKey, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		sharedKeyByKey[o.ID] = append(sharedKeyByKey[o.ID], o)
	}

	for _, rel := range deviceKeys {

		owners, ok := sharedKeyByKey[rel.SharedKeyID]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.SharedKey = o
			rel.R.Loaded.SharedKey = true

			o.R.DeviceKeys = append(o.R.DeviceKeys, rel)

		}
	}

	return nil
}

