type sharedKeyCountPreloader struct {
	DeviceKeys func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
	Videos     func(...bob.Mod[*dialect.SelectQuery]) psql.Preloader
}

func buildSharedKeyCountPreloader() sharedKeyCountPreloader {
	return sharedKeyCountPreloader{
		DeviceKeys: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*SharedKey]("DeviceKeys", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = SharedKeys.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(DeviceKeys.NameAsExpr()),
					sm.Where(psql.Quote(DeviceKeys.Alias(), "shared_key_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
		Videos: func(mods ...bob.Mod[*dialect.SelectQuery]) psql.Preloader {
			return countPreloader[*SharedKey]("Videos", func(parent string) bob.Expression {
				// Build a correlated subquery: (SELECT COUNT(*) FROM related WHERE fk = parent.pk)
				if parent == "" {
					parent = SharedKeys.Alias()
				}

				subqueryMods := []bob.Mod[*dialect.SelectQuery]{
					sm.Columns(psql.Raw("count(*)")),

					sm.From(Videos.NameAsExpr()),
					sm.Where(psql.Quote(Videos.Alias(), "shared_key_id").EQ(psql.Quote(parent, "id"))),
				}
				subqueryMods = append(subqueryMods, mods...)
				return psql.Group(psql.Select(subqueryMods...).Expression)
			})
		},
	}
}

